using MongoDB.Bson;
using MongoDB.Driver;

var client = new MongoClient("mongodb://localhost:27017");
var database = client.GetDatabase("mydb");
var collection = database.GetCollection<Product>("products");

// Insert
await collection.InsertOneAsync(new Product { Name = "Laptop", Price = 999.99m });

// Find
var filter = Builders<Product>.Filter.Eq(p => p.Name, "Laptop");
var product = await collection.Find(filter).FirstOrDefaultAsync();

// Update
var update = Builders<Product>.Update.Set(p => p.Price, 899.99m);
await collection.UpdateOneAsync(filter, update);

// Delete
await collection.DeleteOneAsync(filter);
